/**
 * @summary Checks an odd integer of at least three by trial division.
 * @param {Number} candidate
 * @returns {Boolean}
 */
function isOddPrime(candidate) {
    for (let divisor = 3; divisor * divisor <= candidate; divisor += 2) {
        if (candidate % divisor === 0) {
            return false
        }
    }

    return true
}

